python - <<'PY'
import json
from pathlib import Path

path = Path("data/backtest-prices.json")
if not path.exists():
    raise SystemExit("data/backtest-prices.json is missing")

payload = json.loads(path.read_text(encoding="utf-8"))
symbols = payload.get("symbols")
if not isinstance(symbols, dict):
    raise SystemExit("symbols object is missing")

summary = {}
for symbol in ("QQQ", "SPY"):
    rows = symbols.get(symbol)
    if not isinstance(rows, list):
        raise SystemExit(f"{symbol} is missing")
    if len(rows) < 50:
        raise SystemExit(f"{symbol} has fewer than 50 weekly rows")
    latest = rows[-1].get("date") if isinstance(rows[-1], dict) else None
    if not latest:
        raise SystemExit(f"{symbol} latest date is missing")
    summary[symbol] = {
        "count": len(rows),
        "latest": latest,
    }

with open("snapshot-summary.env", "w", encoding="utf-8") as handle:
    for symbol, values in summary.items():
        handle.write(f"{symbol}_ROW_COUNT={values['count']}\n")
        handle.write(f"{symbol}_LATEST_DATE={values['latest']}\n")
adjusted = json.loads(Path("data/v2/backtest-adjusted-daily.json").read_text(encoding="utf-8"))
if adjusted.get("version") != "adjusted-daily-v2" or adjusted.get("research_only") is not True:
    raise SystemExit("adjusted daily v2 schema metadata is invalid")
for symbol in ("QQQ", "SPY"):
    rows = adjusted.get("symbols", {}).get(symbol, [])
    if len(rows) < 260 or any(not all(field in row for field in ("adjusted_open", "adjusted_high", "adjusted_low", "adjusted_close")) for row in rows):
        raise SystemExit(f"{symbol} adjusted OHLC coverage is invalid")
v2 = json.loads(Path("results/dca_l2/v2/summary.json").read_text(encoding="utf-8"))
if not v2.get("validity", {}).get("valid") or v2["validity"].get("executed_trade_count", 0) <= 0:
    raise SystemExit("DCA-L2 v2 result is invalid or has no executed trades")
PY
